-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql (la tabla enemies con las columnas classification y version).
--
-- Enemigos de Zenless Zone Zero: 220, divididos en jefes (90) y esbirros
-- (130, de los que 57 son elites).
--
-- Fuentes:
--   HoYoWiki (la wiki oficial de HoYoverse) -> textos oficiales en espanol e
--     ingles: afiliacion, clasificacion, version, debilidades, resistencias,
--     informes de combate, trasfondo, botin, imagen y entradas relacionadas.
--   Datos del propio juego (Nanoka) -> rango.
--
-- En Zenless las resistencias no tienen porcentaje: solo se sabe a que
-- elementos resiste cada enemigo. Las versiones relacionadas (miasmaticas,
-- ionizadas, metamorfoseadas...) quedan en variants, con sus propias
-- debilidades.
--
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada.
--
-- Generado el 2026-09-15.

--
-- PARTE 1 de 2 (133 filas). El archivo entero no cabia en el SQL Editor:
-- ejecuta las 2 partes, en cualquier orden.

insert into public.enemies (
  id, game_id, name, name_en, category, rank, faction, classification, version, description, image_url, weaknesses, resistances, variants, skills, drops
)
values
  ('zzz-enemy-1208', 'zenless-zone-zero', 'Faetón del Horizonte Calcinado integrado', 'Integrated - Phaethon of the Scorched Horizon', 'jefe', 'jefe', null, null, null, null, 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/09/10/846fd59b6e217de2ac5e18370c9a7890_5255831861002230980.png', '[]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Informe actual","descripcion":"Unidad de simulación de alto riesgo basada en datos de combate. Es el resultado de una profunda reconstrucción y una sincronización excesiva de la lógica de combate del prototipo. Algunas superan los límites de rendimiento establecidos y representan una amenaza extrema en combate.\n\n La luz precede al dolor.\n El éter descontrolado es como una erupción solar. La silueta de lo que antes era humano se calcina, se desintegra y se transforma para adoptar un aspecto parecido al de un ser etéreo. Las lentes cristalinas vibran en las profundidades de su campo de visión y emiten un resplandor demasiado brillante y cercano, como si alguien hubiera incrustado el sol en sus cuencas de los ojos.\n La consciencia se consume entre las llamas.\n El golpe cae como un reflejo, como un hábito incluso carente del concepto de objetivo. Lo único que hay es un espacio en blanco familiar y asfixiante, como si hace mucho tiempo también hubiera perdido su voz y su peso mientras veía cómo todo sucumbía entre la luz y el calor. Esos fragmentos enterrados surgen junto a las ascuas: la gélida luz del laboratorio, la repentina fuerza incontrolable, los rostros sin vida... Los recuerdos parecen tan reales que incluso producen náuseas y dejan en la mente quemaduras imposibles de borrar.\n «... ¿Quién eres?»\n Aquella voz atraviesa el rugido de la sangre en los oídos para traer consigo durante un instante un nombre desvaído y hacer que su consciencia recobre el aliento momentáneamente. Antes de que su razón quede destruida por completo, hay que tomar una decisión: «No vuelvas a traer una calamidad. Vete... Vete... Vete...»\n «... ¿Que me vaya? ¿A dónde? ¿Con quién? ¿A hacer qué?»\n ...\n «Oh, parece que sí que hicimos una promesa así...»\n «&#34;Debemos atrapar el sol.&#34;»\n\n «Y pensar que tu pecado original volvería a guiarme a cotas más altas casi una década después... Qué ironía, legado de Helios.»\n\n— Un anciano con el cetro de plomo leyendo el informe confidencial de la competición.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1207', 'zenless-zone-zero', 'Kusarikku', 'Kusarikku', 'jefe', 'jefe', null, null, null, null, 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/09/10/50e878593a5aabad2e31b5ecab92ce3d_730868818928489117.png', '[]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Informe actual","descripcion":"Una bestia acorazada nacida de la nada. Se adentra en el abismo siguiendo unos susurros sombríos. Su fuerza bruta es suficiente para desgarrar el espacio. Codicia el poder de los encadenadores y busca la manera de transformar su cuerpo aún inmaduro en un receptáculo que albergue el mal absoluto.\n Con la ayuda de Youkai, la larva de encadenador, el Kusarikku intenta hacerse con el poder del núcleo kármico en el interior de Lindverne, la Dama del Albor.\n Es capaz de empuñar una espada y un martillo cuyas dimensiones desafían la lógica. Sus feroces ofensivas bastan para desencadenar vórtices etéreos y dejar atrás fisuras espaciales breves e inestables. Su instinto de cazadora le permite moverse por este laberinto de fisuras, y su pesado cuerpo muta en un espectro que devora la vida.\n\n «Estas habilidades espaciales son muy prácticas: si va mal, siempre se puede huir... Aunque no es su caso.»\n\n— Un capitán de patrulla que estudia fotograma a fotograma los vídeos de combate.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1206', 'zenless-zone-zero', 'Unidad táctica autónoma: conquistador', 'Autonomous Tactical Unit - Conqueror', 'jefe', 'jefe', null, null, null, null, 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/09/10/7fd25d6d2459abaa90c7ceb7f3dc772d_33736407244174862.png', '[]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Informe actual","descripcion":"Unidad de combate extraordinaria desplegada por el Grupo Porvenir.\n Al adaptarse a la situación en el sitio y aprovechar los recursos al máximo, el personal de combate recupera una gran cantidad de alealumen de Arrecife Oculto para mejorar la armadura del conquistador.\n Teniendo en cuenta la falta de técnicas de procesamiento, el alealumen no se pudo integrar correctamente en la estructura principal del meca. Sin embargo, su rigidez y resistencia estructural excepcionales permiten reforzar considerablemente la durabilidad de la armadura.\n\n «¿El alealumen no es tan valioso? No deberíamos usarlo como si fuera acero, ¿no?»\n «Dime, ¿este meca es genial o no?»\n\n— Entre las tropas de Porvenir encargadas de transportar las nuevas armaduras, parece haber un fan de las películas cargadas de efectos especiales...","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1205', 'zenless-zone-zero', 'Guardia de Patrulla Aérea', 'Airspace Patrol Shieldguard', 'esbirro', 'normal', null, null, null, null, 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/09/10/ab69ece1d0f5ea3f5de95d71821dd8a6_8849387101038530125.png', '[]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Informe actual","descripcion":"Guardias del Departamento de Patrulla Aérea de Roscaelifer, equipados con armamento forjado por la familia Flint, encargados de conservar el orden de la ciudad.\n\n Las unidades de patrulla del Departamento de Patrulla Aérea son reconocidas por su disciplina estricta y su gran eficiencia operativa.\n Los miembros del Departamento de Patrulla Aérea tienen múltiples orígenes, pero la mayoría de los mandos de base con rango de suboficial o superior proceden de una familia prestigiosa de larga tradición: la familia de L''Azur.\n Los cargos militares no se heredan; su estatus actual lo ha obtenido gracias a que los miembros de la familia se entrenan en el combate desde una temprana edad. La mayoría de sus miembros jóvenes consideran que unirse a las unidades de patrulla es el rito para convertirse en adultos. Ser un de L''Azur implica convertirse en un referente intachable en las unidades. «¿Con esos movimientos de pacotilla pretendes desafiar a la Srta. Sigrid? Vete a entrenar un poco más.»\n\n— Un instructor jubilado que reprende a los reclutas en el campo de entrenamiento.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1204', 'zenless-zone-zero', 'Lancero de la patrulla aérea', 'Airspace Patrol Spearguard', 'esbirro', 'normal', null, null, null, null, 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/09/10/c4350bfaca37bb3c9e42da3fe25751e5_1234420288212435455.png', '[]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Informe actual","descripcion":"Lanceros del Departamento de Patrulla Aérea de Roscaelifer, equipados con lanzas de alealumen. Poseen una gran movilidad.\n\n Las unidades de patrulla del Departamento de Patrulla Aérea son reconocidas por su disciplina estricta y su gran eficiencia operativa.\n Los miembros del Departamento de Patrulla Aérea tienen múltiples orígenes, pero la mayoría de los mandos de base con rango de suboficial o superior proceden de una familia prestigiosa de larga tradición: la familia de L''Azur.\n Los cargos militares no se heredan; su estatus actual lo ha obtenido gracias a que los miembros de la familia se entrenan en el combate desde una temprana edad. La mayoría de sus miembros jóvenes consideran que unirse a las unidades de patrulla es el rito para convertirse en adultos. Ser un de L''Azur implica convertirse en un referente intachable en las unidades. «¿Qué sabrás tú? ¡Si la Srta. Lindverne así lo ha hecho será por algo!»\n\n- Unos nuevos reclutas que expresan dudas siempre escuchan el mismo sermón de los veteranos al unísono.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1203', 'zenless-zone-zero', 'Vanguardia de la Patrulla Aérea', 'Airspace Patrol Vanguard', 'esbirro', 'normal', null, null, null, null, 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/09/10/818b992dbbba6eaa02b219663aef1542_2342245979740755257.png', '[]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Informe actual","descripcion":"Unidad de vanguardia del Departamento de Patrulla Aérea de Roscaelifer, equipada con espadas de alealumen. Las hojas poseen una excelente conectividad etérea. Pueden resonar con el éter, canalizar la energía hacia la hoja para potenciar más aún su potencia ofensiva.\n\n Las unidades de patrulla del Departamento de Patrulla Aérea son reconocidas por su disciplina estricta y su gran eficiencia operativa.\n Los miembros del Departamento de Patrulla Aérea tienen múltiples orígenes, pero la mayoría de los mandos de base con rango de suboficial o superior proceden de una familia prestigiosa de larga tradición: la familia de L''Azur.\n Los cargos militares no se heredan; su estatus actual lo ha obtenido gracias a que los miembros de la familia se entrenan en el combate desde una temprana edad. La mayoría de sus miembros jóvenes consideran que unirse a las unidades de patrulla es el rito para convertirse en adultos. Ser un de L''Azur implica convertirse en un referente intachable en las unidades. «¿No crees que esta espada es... demasiado pesada?» «¡¿Cómo?! ¿Tú también lo crees? Yo creía que era porque no tengo suficiente fuerza, así que no me he atrevido a decirlo...»\n\n— Una queja discreta que, contra todo pronóstico, tuvo eco entre los miembros de la patrulla.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1184', 'zenless-zone-zero', 'Aparición Infernal', 'Infernal Revenant', 'jefe', 'jefe', 'Mutaciones etéreas', 'Ser etéreo', '3.1', 'Un ser etéreo que regresó del Lago Fluorocandente. Fue un Carnicero del Callejón derrotado por el jefe supremo Pompey que, tras su caída en el Lago Fluorocandente, no solo no fue consumido por las llamas, sino que quedó envuelto en cristales formados como subproducto de la combustión del éter. Entre las llamas, su coraza se fundía y se desprendía sin cesar, para luego cubrirse de nuevos cristales. Tras soportar un tormento interminable digno del mismísimo infierno, su cuerpo se endureció como una armadura y adquirió la capacidad de moverse libremente entre el fuego. Después de una larga y errante vigilia que parecía olvidada por el tiempo, tuvo la fortuna de descubrir una fisura espacial en el fondo del Lago Fluorocandente, a través de la cual accedió al Laberinto Divino: la Cavidad Papago. Sin embargo, aquello no era más que caer en otro infierno. Parece haber sufrido una derrota devastadora y, desde entonces, una fuerza desconocida lo impulsa a obsesionarse con apoderarse del éter especial disperso por el laberinto. Pero hace ya mucho tiempo que es incapaz de distinguir si lo que ese éter alberga es redención o profanación.

«¡Cada vez que pasa ese tipo en llamas, la temperatura sube disparada! ¡Voy a solicitar un subsidio por calor extremo!»
— «Diario de observaciones del Puesto de Avanzada Papago».', 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/08/11/225b9cbdedcbc23d824d08b6bdc19a2e_6847280996721958425.png', '["Glacial","Aéreo"]'::jsonb, '[{"elemento":"Físico","valor":null}]'::jsonb, null, '[{"nombre":"Informe de combate","descripcion":"Durante el combate, la Aparición Infernal usará su arma para lanzar poderosos ataques contra el jugador. Al recibir cierta cantidad de daño, entrará en el «estado infernal». En el «estado infernal», será necesario activar con éxito un bloqueo en cadena para resistir algunos de sus ataques. La Aparición Infernal también puede invocar una lluvia de fuego que inflige daño continuo a los agentes. Por cada pedernal destruido, se obtiene un «escudo infernal» y se restaura Energía. Al destruir tres pedernales, se pondrá fin a la lluvia de fuego. En el modo operación Bagel, la Aparición Infernal dejará de tener debilidades y resistencias de atributos.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1183', 'zenless-zone-zero', 'Ulidim', 'Ulidim', 'jefe', 'jefe', 'Mutaciones etéreas', 'Ser etéreo', '3.1', 'Un ser etéreo infame que deambula por el Laberinto Divino de la Cavidad Papago. Si el campo sonoro alucinógeno de la Cavidad Papago es la trampa que atrae a las presas al laberinto, entonces ulidim es el sabueso que da caza a las víctimas atrapadas en él. La habilidad especial y lo más aterrador de ulidim radica en su capacidad para aparecer de repente desde cualquier lugar u objeto dentro de las ilusiones de la Cavidad, ya sea en un rincón de estas o a través de pertenencias del pasado que albergan los recuerdos felices de los fallecidos, infligiendo un golpe doble tanto físico como mental a sus víctimas. Motivo por el que también se le conoce como el «sabueso ancestral». Su principio fundamental radica en su habilidad especial para ignorar las ilusiones creadas por el campo sonoro alucinógeno y atravesar libremente la estructura de la Cavidad. Debido a sus aterradoras características y apariencia, ulidim es una de las amenazas más comunes y temibles en los encargos de exploración de la Cavidad Papago. Los bangbús del Puesto de Avanzada Papago se aterrorizan con solo escuchar su nombre, e incluso entre los bangbús circulan terroríficas leyendas sobre ulidim. Existen múltiples ejemplares de ulidim dentro de la Cavidad, su tarea habitual es patrullar rutas y sectores fijos para mantener la estabilidad de las ondas sonoras alucinógenas en el interior de la Cavidad Papago. Una vez que descubren a un intruso cuyo comportamiento interfiere con el proceso de expansión estable de la Cavidad, lo perseguirán hasta eliminarlo.

«En ese laberinto sin principio ni fin, quizás ser devorado por completo por ese temible sabueso sea una especie de liberación.»
— «Guía del viajero de Cavidades: memorias de Papago».', 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/08/11/17bdfcbbaf6d3ad00f53303b8719a6af_5252328818257316209.png', '["Glacial","Aéreo"]'::jsonb, '[{"elemento":"Físico","valor":null}]'::jsonb, null, '[{"nombre":"Informe de combate","descripcion":"Durante el combate, «ulidim» cambiará de arma según la situación y usará la teletransportación para lanzar ataques sorpresa. Esquiva sus lanzas y bloquea continuamente sus veloces combos de golpes para tomar poco a poco la iniciativa en el combate. «Ulidim» ya no tendrá debilidades ni resistencias a atributos en el modo de juego de la operación Bagel.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1182', 'zenless-zone-zero', 'Girtablilu: estancación aberrante', 'Girtablullu - Stagnant Aberrant', 'jefe', 'jefe', 'Mutaciones etéreas', 'Ser etéreo', '3.1', 'La bestia erguida al borde del abismo desata sin tapujos un fuego voraz y codicioso. Su deseo es devorar la semilla de la que brotará el mal absoluto y ascender como emisaria del señor del abismo. La larva de encadenador, conocida como Girtablilu, intentó consumir el poder del núcleo kármico en el interior de la Dama del Albor Dracaene y la estancación aberrante es, precisamente, el resultado de ese intento fallido de absorción y ascensión. Al perder el control de la energía del núcleo kármico, su cuerpo esculpido en éter sufrió una mutación desbocada y ahora su horrible y monstruosa figura desata una malicia impulsada por la ambición y la codicia.

«Comer de todo no te traerá nada bueno.»', 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/08/11/51fadd839bc200d4eed777aa435d3a6a_9117815369305647244.png', '[]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Informe de combate","descripcion":"Durante el combate, Girtablilu: estancación aberrante activa en repetidas ocasiones su barrera corruptiva y lucha valiéndose de una gran variedad de armas. La primera vez que activa su barrera, no entra en el estado de Aturdimiento, por lo que es necesario destruirla lo antes posible. Cuando vuelve a activarla, comienza a recargar energía de forma continua mientras acumula valor de barrera corruptiva. Para obtener ventaja, es necesario infligirle constantemente una gran cantidad de daño y así suprimir dicha recarga.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1181', 'zenless-zone-zero', 'Girtablilu integrado', 'Integrated - Girtablullu', 'jefe', 'jefe', 'Mutaciones etéreas', 'Ser etéreo', '3.1', 'Unidades simuladas de alto riesgo basadas en datos de combate real. Al reconstruir en profundidad y sobreajustar la lógica de combate de sus prototipos, ciertos individuos han superado los límites de rendimiento estándar, lo que representa una amenaza de combate excepcionalmente alta. Un ser etéreo de alto riesgo de aspecto similar al de un escorpión que lucha con una lanza de color gris ceniza. Sus robustas extremidades inferiores y su ágil torso se combinan para crear una máquina de combate que resulta tanto devastadora como sumamente móvil. Al desplazarse a través de agujeros de gusano, recorre la Cavidad Scamall en busca de su próxima víctima para atraerla a su nido. A diferencia de los seres etéreos que se han transformado a partir de fauna o maquinaria corrompidas, esta criatura ha sido engendrada por algo mucho más terrorífico, y porta un aura etérea sin igual.

«¡No hay ningún modo para la fobia a los insectos en los ajustes!»
— Una miembro de la guardia adicta a los juegos de combate en RV y con miedo a los artrópodos', 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/08/11/2187d3a2b309a0e0b7aff808fb72a5d2_6077061928831109634.png', '[]'::jsonb, '[]'::jsonb, '[{"id":"zzz-enemy-1181","nombre":"Girtablilu integrado","debilidades":[],"resistencias":[]},{"id":"zzz-enemy-1133","nombre":"Girtablilu","debilidades":["Aéreo"],"resistencias":[]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"Durante el combate, el Girtablilu utilizará con frecuencia los agujeros de gusano de éter que crea para desplazarse y atacar por sorpresa, además de ejecutar varios movimientos que requieren que dos agentes bloqueen al mismo tiempo. Si se activa un bloqueo en cadena con éxito, se puede reducir rápidamente la barrera corruptiva. Asimismo, el Girtablilu convocará a sus esbirros en momentos específicos para lanzar ataques consecutivos. Si se bloquean los ataques de los esbirros con éxito, se puede activar la conversión activa para obtener ventaja en el combate.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1135', 'zenless-zone-zero', 'Exohormiga mutante', 'Mutant Formicarrier', 'esbirro', 'normal', 'Entes corrompidos', 'Ser etéreo', '3.0', 'Esta unidad, diseñada originalmente como una caja de almacenamiento de suministros estándar, estaba equipada con un sistema antirrobo electrónico de alta gama capaz de frustrar a los ladrones incluso sin alimentación externa.
En una ocasión, un grupo de contrabandistas logró interceptar un cargamento, solo para descubrir que no podían eludir sus permisos de seguridad. Tras agotar todas las opciones, abandonaron la caja en una Cavidad. Para sorpresa de todos, varias exohormigas acabaron fusionándose con ella, transformándola en un nido móvil y estableciendo su hogar en su interior como si fueran cangrejos ermitaños. Los saqueadores de Cavidades veteranos conocen el secreto para abrirla: no te molestes en hackear la cerradura, solo dales una paliza a las exohormigas que viven dentro. Este incidente sirve como una confirmación más de la famosa reflexión de cierto pensador: la destrucción llega cuando algo se rompe desde el exterior, mientras que la renovación surge cuando se rompe desde el interior.
Al menos, eso es indudablemente cierto para esta caja en particular.

«Espera... ¡¿me estás diciendo que a mi cargamento y a mis deniques les han salido patas y se han marchado?!»
— Saqueador de Cavidades novato enfurecido', 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/07/07/808bbfa369898d319ba1c6a1ba44aa46_1577514912879111640.png', '["Etéreo"]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Informe de combate","descripcion":"Durante el combate, la tímida exohormiga mutante se esconde dentro de cofres del tesoro. Si alguien intenta arrebatarle su botín, saldrá corriendo... para salvar la vida.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1133', 'zenless-zone-zero', 'Girtablilu', 'Girtablullu', 'jefe', 'jefe', 'Mutaciones etéreas', 'Ser etéreo', '3.0', 'Un ser etéreo sumamente peligroso de aspecto similar al de un escorpión que lucha con una lanza de color gris ceniza. Sus robustas extremidades inferiores y su ágil torso se combinan para crear una máquina de combate que resulta tanto devastadora como sumamente móvil. Al desplazarse a través de agujeros de gusano, recorre la Cavidad Scamall en busca de su próxima víctima para atraerla a su nido. A diferencia de los seres etéreos que se han transformado a partir de fauna o maquinaria corrompidas, esta criatura ha sido engendrada por algo mucho más terrorífico, y porta un aura etérea sin igual.

«¡No hay ningún modo para la fobia a los insectos en los ajustes!»
— Una miembro de la guardia adicta a los juegos de combate en RV y con miedo a los artrópodos', 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/06/22/d5e44b7a158da84844ee76231245fa32_8918509333480805819.png', '["Aéreo"]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Informe Actual","descripcion":"El objetivo de esta cacería es un ser etéreo con aspecto de escorpión. A pesar de ser muy fuerte, su aura etérea es extremadamente débil. Es muy diferente a los seres etéreos vistos hasta ahora.\n· Durante la operación, podrás obtener resonios de las series etéreo, duelo y anómalo.","tipo":"informe","elemento":null},{"nombre":"Informe de combate","descripcion":"Durante el combate, Girtablilu desgarra el espacio circundante y utiliza agujeros de gusano etéreos autogenerados para desplazarse de forma impredecible y lanzar ataques sorpresa. Tras activar la barrera corruptiva, Girtablilu ejecuta un poderoso ataque que requiere la colaboración de dos agentes para bloquearlo. Activar con éxito un bloqueo en cadena en el momento oportuno puede otorgar una ventaja táctica.","tipo":"informe","elemento":null}]'::jsonb, '[{"nombre":"Crédito proxy","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/10/09/15884296/4f5ce091ef73f3a21968a7a428d507d3_2684785628069418773.png","rareza":null,"cantidad":400},{"nombre":"Méritos de investigación","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/10/09/15884296/0c3989934b5a617dfbae9dc419b6b398_5119480213208239104.png","rareza":null,"cantidad":null},{"nombre":"Disco original de alta fidelidad","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/c84ef83ab48b2f606e0140f9a9a8a02a_9002253415738654774.png","rareza":null,"cantidad":null},{"nombre":"Disco original de cancelación de ruido","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/830f09230106b5c4c3efc70c30753a5e_6017699719454723390.png","rareza":null,"cantidad":null},{"nombre":"Disco original de amplificación de sonido","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/2e283d0cda6151ba81a45b27b828c2da_6000235188262046317.png","rareza":null,"cantidad":null},{"nombre":"Cubierta deteriorada","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2026/07/15/19629685/7f05a84f1f7d30a5b29d5a4ea8b5a620_4283329586638697008.png","rareza":null,"cantidad":1},{"nombre":"Chip residual","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/03/10/19629685/58d2404e7866383544fd6d71024ef000_4461795690864767485.png","rareza":null,"cantidad":null},{"nombre":"Denique","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","rareza":null,"cantidad":null},{"nombre":"Revestimiento etéreo","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/ecc3811894203ad2e06b8f9fa721309d_2906289886923134148.png","rareza":null,"cantidad":null},{"nombre":"Revestimiento cristalizado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/ab9edaca8b97e00eabf1cd043a378bdb_4476253967579736265.png","rareza":null,"cantidad":null}]'::jsonb),
  ('zzz-enemy-1132', 'zenless-zone-zero', 'Unidad de apoyo autónoma: centinela del espacio aéreo', 'Autonomous Assault Unit - Airspace Sentinel', 'jefe', 'jefe', 'Especial', 'Ser etéreo', '3.0', 'Una unidad especial de combate pesado desplegada por el Departamento de Patrulla Aérea de Roscaelifer. Como la culminación de la tecnología militar del Departamento de Patrulla Aérea, está posicionada en las instalaciones de energía en los niveles inferiores de la isla en el cielo.
Durante el servicio de patrulla, permanece en una configuración de torreta fija, proporcionando un estruendoso apoyo de fuego pesado a las fuerzas terrestres. Cuando su base estabilizada se transforma en una estructura cuadrúpeda, se convierte en un meca de combate pesado de gran movilidad capaz de dominar el campo de batalla.
Sirve como una línea de defensa fiable contra las incursiones de seres etéreos causadas por las singularidades de fuga. Sin embargo, si se ve afectado por la corrupción etérea y pierde el control, se convierte en una grave amenaza para el Sector de Energía.

«¡Si algún enemigo se atreve a invadir, me desplegaré en mi forma de meca!»
— Un piloto guardián recién alistado espera en secreto que aparezcan mecas y naves de guerra del enemigo en el horizonte', 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/06/22/f1e74b994f76d6dd5972a5d14545938a_8483429507239710002.png', '["Glacial","Aéreo"]'::jsonb, '[{"elemento":"Etéreo","valor":null}]'::jsonb, null, '[{"nombre":"Informe actual - Sala de desafió experto","descripcion":"En esta batalla, unidad de apoyo autónoma: centinela del espacio aéreo obtiene el siguiente efecto:\nDespués de que un agente bloquee un ataque, el daño recibido aumenta en un 10 / 13.3 / 16.7 / 20 % durante 15 s.\n\nMeca de combate estándar del Departamento de Patrulla Aérea que cuenta con una gran potencia de fuego... que lo convierte en un oponente aún más complicado después de corromperse.","tipo":"informe","elemento":null},{"nombre":"Información de combate","descripcion":"Cuando el centinela del espacio aéreo ejecuta ataques específicos, o después de que un agente los bloquea, expone su núcleo. Ataca su núcleo expuesto para infligir daño adicional y provocar el estado de parte dañada.","tipo":"informe","elemento":null}]'::jsonb, '[{"nombre":"Crédito proxy","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/10/09/15884296/4f5ce091ef73f3a21968a7a428d507d3_2684785628069418773.png","rareza":null,"cantidad":400},{"nombre":"Disco original de cancelación de ruido","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/830f09230106b5c4c3efc70c30753a5e_6017699719454723390.png","rareza":null,"cantidad":null},{"nombre":"Disco original de amplificación de sonido","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/2e283d0cda6151ba81a45b27b828c2da_6000235188262046317.png","rareza":null,"cantidad":null},{"nombre":"Datos de alta dimensionalidad: circuito de erosión profunda","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2026/07/08/73555894/5c87dc430506f57b51a7b7419e24058c_7613117060854501247.png","rareza":null,"cantidad":1},{"nombre":"Denique","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","rareza":null,"cantidad":null}]'::jsonb),
  ('zzz-enemy-1131', 'zenless-zone-zero', 'Pesadilla primordial integrada: «Creador»', 'Integrated - Primordial Nightmare - "The Creator"', 'jefe', 'jefe', 'Especial', null, '3.0', 'Unidades simuladas de alto riesgo basadas en datos de combate real. Al reconstruir en profundidad y sobreajustar la lógica de combate de sus prototipos, ciertos individuos han superado los límites de rendimiento estándar, lo que representa una amenaza de combate excepcionalmente alta.', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2026/08/15/19629685/db7768f5b2c182d1f49b7c7aa3a45cb0_1733394241943563471.png', '[]'::jsonb, '[]'::jsonb, '[{"id":"zzz-enemy-1131","nombre":"Pesadilla primordial integrada: «Creador»","debilidades":[],"resistencias":[]},{"id":"zzz-enemy-994","nombre":"Pesadilla primordial: Creador","debilidades":["Físico"],"resistencias":[{"elemento":"Glacial","valor":null},{"elemento":"Etéreo","valor":null}]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"La pesadilla primordial integrada está fortalecida, lo que mejora todas sus habilidades de combate. La pesadilla primordial integrada puede entrar y salir libremente del dominio miasmático. Incluso cuando no se encuentra en el dominio miasmático, el escudo miasmático puede protegerla y evitar que se le provoque Aturdimiento. Solo tras romper el escudo miasmático se le puede provocar Aturdimiento. Cuando la pesadilla primordial integrada se recupera del Aturdimiento, la protección del escudo miasmático vuelve a activarse.\nDurante el combate, la pesadilla primordial integrada utiliza técnicas de control. Responder perfectamente a cada ataque puede otorgar una ventaja en la batalla.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1130', 'zenless-zone-zero', 'Doppelgänger de Billy Estelar', 'Doppelganger - Starlight - Billy', 'jefe', 'jefe', 'Mutaciones etéreas', 'Ser etéreo', '3.0', 'Incluso dentro de los ionizados, conocidos por su rareza y sus cualidades insólitas, el doppelgänger ionizado es único en su especie.
Estos seres son capaces de cubrir sus cuerpos con una capa de iones de éter activos especiales, lo cual les permite replicar con precisión la apariencia de su objetivo. Su precisión es tal que resulta prácticamente imposible apreciar diferencias tanto en textura como en detalles del objetivo original.
Lo que todavía resulta más complicado es que pueden llegar a imitar las poderosas e intimidantes técnicas de combate de sus objetivos. Nadie sabe de dónde obtienen la información para lograr imitar a ciertos sujetos. Algunos rumores indican que pueden leer la mente, lo cual les permitiría elegir la forma más adecuada a partir de los recuerdos de su oponente, transformarse en ella y atacar sin piedad.

«¡Tonterías! Si de verdad pudiera identificar mis miedos más profundos, ¡se convertiría en una feroz señora de mediana edad con una chancla en la mano! ¡Así es, mi mayor miedo es mi vieja!»
— Comentario de un saqueador de Cavidades en la red proxy', 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/06/22/46cc13e5688fb1d861bf6fcefc4e63b2_3407329367473798022.png', '["Ígneo","Eléctrico"]'::jsonb, '[{"elemento":"Físico","valor":null}]'::jsonb, '[{"id":"zzz-enemy-1130","nombre":"Doppelgänger de Billy Estelar","debilidades":["Ígneo","Eléctrico"],"resistencias":[{"elemento":"Físico","valor":null}]},{"id":"zzz-enemy-711","nombre":"Doppelgänger ionizado","debilidades":[],"resistencias":[]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"Durante el combate, el doppelgänger de Billy Estelar ataca con potentes embestidas en motocicleta y Patadas voladoras caballerescas. Si un agente ejecuta un apoyo defensivo en el momento oportuno, puede derribarlo de la moto. Tras usar Neumáticos de alta tracción, el doppelgänger de Billy Estelar entra en un estado de fortalecimiento y es necesario ejecutar un apoyo defensivo dos veces consecutivas para derribarlo.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1129', 'zenless-zone-zero', 'Promesa Centelleante: Billy', 'Shining Promise - Billy', 'jefe', 'jefe', 'Especial', 'Maquinaria', '3.0', 'Un amigo de confianza, un guerrero experimentado, el primer maestro en el camino de la batalla.
¡Mira! ¡La insignia de la galaxia resplandeciente está resonando! ¡Escucha! ¡Un ritmo potente está sonando! Los motores rugen, las chispas de los disparos saltan y el calentamiento por fin ha terminado. El caballero carga su altavoz y se incorpora al campo de batalla.
¿Estás {♂: listo, amigo mío?}{♀: lista, amiga mía?} ¡Es hora del espectáculo!

«¡Tal como se esperaba {♂: del dependiente}{♀: de la dependienta}! ¡Hora de ponerse serios!»
«¡No puede ser! ¿Me voy a enfrentar al campeón invicto? ¿De verdad?»
— ¡En total desventaja y sin opciones, un enfrentamiento épico!', 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/06/22/dbe46f7b6457b009f548f7a685838fdd_1524586711403581561.png', '["Ígneo","Eléctrico"]'::jsonb, '[{"elemento":"Físico","valor":null}]'::jsonb, '[{"id":"zzz-enemy-1129","nombre":"Promesa Centelleante: Billy","debilidades":["Ígneo","Eléctrico"],"resistencias":[{"elemento":"Físico","valor":null}]},{"id":"zzz-enemy-1130","nombre":"Doppelgänger de Billy Estelar","debilidades":["Ígneo","Eléctrico"],"resistencias":[{"elemento":"Físico","valor":null}]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"Durante el combate, Promesa Centelleante: Billy ataca con potentes embestidas en motocicleta y Patadas voladoras caballerescas. Si un agente ejecuta un apoyo defensivo en el momento oportuno, puede derribarlo de la moto. Tras usar Neumáticos de alta tracción, Promesa Centelleante entra en un estado de fortalecimiento y es necesario ejecutar un apoyo defensivo dos veces consecutivas para derribarlo.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1128', 'zenless-zone-zero', 'Escorpiosqueleto metamorfoseado', 'Metamorphosed - Scorpse', 'jefe', 'jefe', 'Mutaciones etéreas', 'Ser etéreo', '3.0', 'Aquel que se despoja de un caparazón destrozado en la oscuridad, renacido a través de la corrupción, habiendo abandonado su forma caída.

En las tierras desoladas, completamente devoradas por la Cavidad, dormía en paz... hasta que llegó «aquel poder».
Este poder invasivo y contaminante, como un artesano habilidoso pero malévolo, lo rellenó con una energía oscura más pura, transformándolo en lo que ahora es, el «escorpiosqueleto miasmático».
Poco a poco, parece haber comprendido el truco de la «existencia» a través de la imitación. Puede dividir su energía miasmática para crear múltiples «mimos» aparentemente reales.
Estos mimos poseen un poder ofensivo casi idéntico al del original. Emplean deslumbrantes ataques desde múltiples ángulos para ocultar la singular y letal «verdad».
Cuando te enfrentes a su asedio, recuerda bien esto: todo lo que ves es ilusorio, todo lo que perciben tus sentidos es una trampa.

«Solo eliminando todas las distracciones y alcanzando la lucidez para ver la única &#34;verdad&#34;, podrás encontrar un atisbo de esperanza en esta danza ilusoria de la muerte.»
— Valiente explorador', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2026/08/07/19629685/745331a3f35cdd847ba4814a92d52ccd_4644118548091233890.png', '["Eléctrico","Aéreo"]'::jsonb, '[{"elemento":"Glacial","valor":null}]'::jsonb, '[{"id":"zzz-enemy-1128","nombre":"Escorpiosqueleto metamorfoseado","debilidades":["Eléctrico","Aéreo"],"resistencias":[{"elemento":"Glacial","valor":null}]},{"id":"zzz-enemy-996","nombre":"Caminante miasmático: escorpiosqueleto","debilidades":["Físico","Etéreo"],"resistencias":[{"elemento":"Ígneo","valor":null}]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"Durante el combate, el escorpiosqueleto metamorfoseado se oculta y utiliza sus mimos para atacarte. Al activar el apoyo defensivo o el contraataque contra los mimos, el escorpiosqueleto metamorfoseado quedará derribado y paralizado durante un tiempo. Al activar la barrera corruptiva, el escorpiosqueleto metamorfoseado invocará más mimos para realizar ataques coordinados. Además, el escorpiosqueleto metamorfoseado escupe grandes cantidades de veneno que contienen sacos de huevos de araña explosiva, lo que causa daño por múltiples explosiones.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1127', 'zenless-zone-zero', 'Avarus metamorfoseado', 'Metamorphosed - Avarus', 'jefe', 'jefe', 'Mutaciones etéreas', 'Ser etéreo', '3.0', null, 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2026/08/07/19629685/b6bb23f849cf1ac302ba7f36bf4cfa96_1391301088155091233.png', '["Físico","Aéreo"]'::jsonb, '[{"elemento":"Ígneo","valor":null}]'::jsonb, '[{"id":"zzz-enemy-1127","nombre":"Avarus metamorfoseado","debilidades":["Físico","Aéreo"],"resistencias":[{"elemento":"Ígneo","valor":null}]},{"id":"zzz-enemy-826","nombre":"Devorador miasmático: Avarus","debilidades":["Ígneo","Etéreo"],"resistencias":[{"elemento":"Glacial","valor":null}]}]'::jsonb, '[{"nombre":"Informe","descripcion":"El Avarus metamorfoseado utiliza su enorme cuerpo para realizar ataques rodantes. Al ejecutar un apoyo defensivo para contratacar este movimiento 3 veces seguidas, puedes interrumpir su ataque rodante y exponer su punto débil. Cuando recibe cierta cantidad de daño durante el combate, activa la barrera corruptiva.","tipo":"informe","elemento":null},{"nombre":"Informe actual","descripcion":"Aquel que se despoja de un caparazón destrozado en la oscuridad, renacido a través de la corrupción, habiendo abandonado su forma caída.\n\nEn los informes de la Asociación de Investigación de Cavidades, Avarus recibe burlonamente el apodo de «la encarnación de la gula», pues su figura barrigona lo hace parecer un monstruo perezoso a punto de quedarse dormido. Sin embargo, no se debe subestimar su poder. Según los registros de observación, Avarus puede contraer su cuerpo hasta convertirse en una bola y lanzar ataques violentos contra sus objetivos a una velocidad asombrosa.\nEn cuanto a por qué mantiene esa figura tan redonda a pesar de su intenso nivel de actividad física, eso es algo que la Asociación sigue investigando.\n\n«Cuando rueda, me recuerda a mi hámster, solo que un poco más grande.»\n«¿Solo un poco más grande?»\n— Anotaciones de una charla casual entre dos investigadores de Cavidades","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1126', 'zenless-zone-zero', 'Hormigonera tarasca pesada metamorfoseada', 'Metamorphosed - Tarasque Mixer', 'esbirro', 'elite', 'Mutaciones etéreas', 'Ser etéreo', '3.0', 'Aquel que se despoja de un caparazón destrozado en la oscuridad, renacido a través de la corrupción, habiendo abandonado su forma caída.

Según las observaciones de la Asociación de Investigación de Cavidades, el torso de la hormigonera tarasca pesada almacena toda clase de líquidos etéreos de diferentes intensidades. Al mezclarlos, es capaz de crear una reacción en cadena compleja que libera energía destructiva con una potencia similar a la artillería del Ministerio de Defensa.
Los investigadores más experimentados han aprendido a moverse con discreción para evitar ser atrapados en la línea de fuego.

«Al inclinar su cabeza frente a mí, pensé que se trataba de un regalo de bienvenida. Pero cuando la recámara de su cañón se iluminó, me di cuenta de que era un regalo de despedida.»
— Palabras de un investigador experimentado mientras narraba su experiencia para «Té en la Cavidad»', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2026/08/07/19629685/dd066b7bbb5e566c7b2d008cce27d1fe_4901838569000905482.png', '["Físico","Glacial"]'::jsonb, '[]'::jsonb, '[{"id":"zzz-enemy-1126","nombre":"Hormigonera tarasca pesada metamorfoseada","debilidades":["Físico","Glacial"],"resistencias":[]},{"id":"zzz-enemy-456","nombre":"Hormigonera tarasca","debilidades":["Eléctrico","Etéreo"],"resistencias":[]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"Durante el combate, la hormigonera tarasca pesada metamorfoseada ataca a los enemigos cercanos con sus garras mecánicas y dispara un rayo láser continuo a los objetivos lejanos.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1125', 'zenless-zone-zero', 'Lahmus', 'Lahmu', 'esbirro', 'elite', 'Mutaciones etéreas', 'Ser etéreo', '3.0', 'Según los informes de defensa del Departamento de Patrulla Aérea, los Lahmus se encuentran entre los seres etéreos autóctonos más comunes de Roscaelifer. Sus garras afiladas como cuchillas y su excepcional movilidad los han convertido en un dolor de cabeza constante para innumerables miembros de la Patrulla Aérea.
Al representar la medida justa de amenaza, los Lahmus se han convertido en el referente no oficial del Departamento de Patrulla Aérea para medir la capacidad de combate. Derrotar a uno se considera la prueba de que un oficial puede valerse por sí mismo en el terreno.

«Oye, ¿te has enterado? ¡Dicen que la comandante Sigrid puede acabar con cien Lahmus con una sola mano!»
«¡Entonces, si usara las dos manos, serían doscientos! ¡La comandante Sigrid es increíble!»
«¡Cabeza hueca, así no es como funciona! Si la comandante Sigrid usara las dos manos... ¡probablemente podría acabar con diez mil Lahmus!»
— Nuevos reclutas entusiasmados en un evento de orientación del Departamento de Patrulla Aérea', 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/06/22/77f31c5b483de44f5963f70779cec500_2116495471439333987.png', '["Glacial","Eléctrico"]'::jsonb, '[{"elemento":"Físico","valor":null}]'::jsonb, null, '[{"nombre":"Informe de combate","descripcion":"Durante el combate, los Lahmus utilizan sus cuatro enormes garras para ejecutar ataques cuerpo a cuerpo, aplastando una y otra vez a cualquier objetivo que se acerque demasiado.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1124', 'zenless-zone-zero', 'Mushussus', 'Mushussu', 'esbirro', 'elite', 'Mutaciones etéreas', 'Ser etéreo', '3.0', 'Los Mushussus son poderosos seres etéreos, conocidos por sus implacables embestidas y sus ataques con proyectiles difíciles de esquivar, lo que los convierte en enemigos muy temidos entre los investigadores.
Más parecidos a unas máquinas de guerra que a unas serpientes enfurecidas, los Mushussus arrollan todo a su paso en el campo de batalla, aplastando cualquier cosa que se interponga en su camino. Solo quienes se han enfrentado a ellos cara a cara pueden comprender lo terroríficos que son.
Circula el rumor de que a los Mushussus les gusta cazar a civiles bangbús. Aunque el Departamento de Patrulla Aérea ha emitido múltiples comunicados para desmentirlo, los bangbús siguen aterrorizados. Incluso equipados con blindaje de combate avanzado, algunos oficiales bangbús aún tiemblan al ver a un Mushussus, lo que reduce notablemente su eficacia en combate.

«¿Y por qué les tienen tanto miedo los bangbús a los Mushussus?»
«¿Acaso a las serpientes no les encanta comer huevos? ¿Y no se parecen los bangbús a una especie de huevos con patas? ¡Que una serpiente con patas se coma a un huevo con patas me parece de lo más razonable!»
«¡¿Cómo va a ser razonable?!»
— Una nota que se ha pasado en secreto por la última fila durante una clase de Estudios sobre las Cavidades de la Academia Aurelia', 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/06/22/f30bca93c03d783f3efcf06658a243f6_6681544592022458648.png', '["Ígneo","Aéreo"]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Informe de combate","descripcion":"Durante el combate, los Mushussus concentran energía etérea en la boca y en los cañones de los hombros para lanzar diversos proyectiles de largo alcance.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1123', 'zenless-zone-zero', 'Motor del observador metamorfoseado', 'Metamorphosed - Beholder Engine', 'esbirro', 'normal', 'Mutaciones etéreas', 'Ser etéreo', '3.0', 'Aquel que se despoja de un caparazón destrozado en la oscuridad, renacido a través de la corrupción, habiendo abandonado su forma caída.

A pesar de que, según la base de datos de la Asociación de Investigación de Cavidades, el motor del observador solo representa un peligro al acercarse a él, en realidad, este ser puede llegar a convertirse en un dolor de cabeza para los investigadores. Cuando su ojo fija su mirada en el objetivo y se abalanza sobre él desde las sombras, hasta los investigadores más experimentados sienten un miedo indescriptible. Y en las Cavidades, normalmente el miedo solo empeora los síntomas de corrupción etérea, lo que termina en desastre.

«La única forma de acabar con el miedo es mirándolo fijamente.»
— Recopilación de consejos de un investigador veterano en el foro «Supernova Hoy»', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2026/08/07/19629685/d85e0a7fce6457869cd3f7df5d29be18_3263565219941212938.png', '["Físico","Aéreo"]'::jsonb, '[]'::jsonb, '[{"id":"zzz-enemy-1123","nombre":"Motor del observador metamorfoseado","debilidades":["Físico","Aéreo"],"resistencias":[]},{"id":"zzz-enemy-471","nombre":"Motor del observador","debilidades":["Eléctrico","Etéreo"],"resistencias":[]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"Durante el combate, el motor del observador metamorfoseado dispara rayos láser desde su ojo y ataca con su cuerpo esférico.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1122', 'zenless-zone-zero', 'Kulullu', 'Kulullu', 'esbirro', 'normal', 'Mutaciones etéreas', 'Ser etéreo', '3.0', 'Gracias a su aspecto espeluznante y grotesco, Kulullu lleva varios años consecutivos encabezando la lista de «factores que afectan a la seguridad nocturna de los niños» de Buastrum.
Sin embargo, a pesar de ese rostro de pesadilla, sus ataques son sorprendentemente sencillos y lentos, casi como si no supusiera una amenaza real... ¿o sí?
Lo cierto es que un solo golpe basta para dejar inconsciente a cualquiera durante días. Con el tiempo, muchos investigadores han acabado por referirse a él con una mezcla de temor y respeto: «el prodigio del bofetón único».
Tal vez Kulullu entienda la esencia de las artes marciales mejor que nadie: concentrar todo el poder en un único golpe y perfeccionarlo.

«¿Alguna vez te han dado un bofetón del tamaño de un saco de arena?»
— La queja de un investigador desde la cama de un hospital tras salir volando varios metros', 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/06/22/b9b24c94a1c40891bc09949c69fa6dd7_5266107539084352714.png', '["Glacial","Aéreo"]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Informe de combate","descripcion":"Durante el combate, Kulullu ejecuta ataques a distancia y ataques con impulso tras acumular carga. Presta atención para identificarlos y esquivarlos.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1121', 'zenless-zone-zero', 'Guardiabú urbano metamorfoseado', 'Metamorphosed - City Guardboo', 'esbirro', 'elite', 'Especial', 'Maquinaria', '3.0', 'Aquel que se despoja de un caparazón destrozado en la oscuridad, renacido a través de la corrupción, habiendo abandonado su forma caída.
Una unidad de combate de élite desplegada por el Departamento de Patrulla Aérea de Roscaelifer. Las marcas azules en el chasis indican que está asignada a operaciones en la Cavidad. Desplegada originalmente para proteger infraestructuras críticas, ha perdido el control debido a los efectos de una singularidad de fuga y de la actividad de la Cavidad. Ahora siembra el caos por los niveles inferiores de la isla en el cielo y en las Cavidades cercanas.
El Guardiabú urbano constituye la columna vertebral de los bangbús guardianes de Roscaelifer, desempeñando funciones de asalto, defensa aérea y seguridad de instalaciones. Para cumplir con estas misiones, está equipado con armamento pesado de aire-tierra.
Aunque el exoesqueleto meca ha perdido el control debido a la corrupción etérea, el bangbú piloto de su interior sigue funcionando con normalidad y espera en modo de suspensión la oportunidad perfecta para escapar.

«¡Neh ohn! ¡Ñah nuneh eñ!
(¡Quería convertirme en un Guardiabú! ¡La jefa Norma se ha puesto tan contenta que incluso me ha dado mis Baterías etéreas favoritas!)»
— Un bangbú de la reserva en entrenamiento. Primera opción: la unidad de mecas del Departamento de Patrulla Aérea', 'https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2026/06/22/f0a43fa5051a4fbf428ab6e8a19b259d_4654049945662624587.png', '["Etéreo","Aéreo"]'::jsonb, '[{"elemento":"Físico","valor":null}]'::jsonb, '[{"id":"zzz-enemy-1121","nombre":"Guardiabú urbano metamorfoseado","debilidades":["Etéreo","Aéreo"],"resistencias":[{"elemento":"Físico","valor":null}]},{"id":"zzz-enemy-1120","nombre":"Guardiabú urbano","debilidades":["Eléctrico","Aéreo"],"resistencias":[]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"Durante el combate, el Guardiabú urbano metamorfoseado alterna el uso de combos a corta distancia y disparos a larga distancia, además de ejecutar ataques de embestida. Usar un apoyo defensivo antes de que ataque puede contrarrestar su ofensiva.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-1120', 'zenless-zone-zero', 'Guardiabú urbano', 'City Guardboo', 'esbirro', 'elite', 'Especial', 'Maquinaria', '3.0', 'Una unidad de combate de élite desplegada por el Departamento de Patrulla Aérea de Roscaelifer. Desplegada originalmente para proteger infraestructuras críticas, ha perdido el control debido a los efectos de una singularidad de fuga y de la actividad de la Cavidad. Ahora siembra el caos por los niveles inferiores de la isla en el cielo y en las Cavidades cercanas.
El Guardiabú urbano constituye la columna vertebral de los bangbús guardianes de Roscaelifer, desempeñando funciones de asalto, defensa aérea y seguridad de instalaciones. Para cumplir con estas misiones, está equipado con armamento pesado de aire-tierra.
Aunque el exoesqueleto meca ha perdido el control debido a la corrupción etérea, el bangbú piloto de su interior sigue funcionando con normalidad y espera en modo de suspensión la oportunidad perfecta para escapar.

